/bin/zsh -lc "mkdir -p docs/acceptance/t1441/evidence-exec-aafae534/screenshots docs/acceptance/t1441/evidence-exec-aafae534/logs && node - <<'NODE'
const { chromium } = require('./web/node_modules/playwright');
(async()=>{
 const out='docs/acceptance/t1441/evidence-exec-aafae534';
 const browser=await chromium.launch({headless:true});
 const page=await browser.newPage({viewport:{width:1440,height:1000}, deviceScaleFactor:1});
 const logs=[];
 page.on('console', m=>logs.push({type:'console', level:m.type(), text:m.text()}));
 page.on('response', r=>{ const u=r.url(); if(u.includes('127.0.0.1:17100')) logs.push({type:'response', status:r.status(), method:r.request().method(), url:u}); });
 await page.goto('http://127.0.0.1:17100/', {waitUntil:'networkidle'});
 await page.screenshot({path:"'`${out}/screenshots/00-initial-full.png`, fullPage:true});
 console.log('"'url', page.url());
 console.log('title', await page.title());
 console.log((await page.locator('body').innerText()).slice(0,2000));
 require('fs').writeFileSync("'`${out}/logs/00-initial-console-network.json`, JSON.stringify(logs,null,2));
 await browser.close();
})();
NODE'
